const body = $input.first().json.body || $input.first().json;
const fieldData = body.entry?.[0]?.changes?.[0]?.value?.field_data || [];
const getField = (name) => fieldData.find(f => f.name === name)?.values?.[0] || '';
return [{ json: {
  source: 'facebook_ad',
  channel: 'sms',
  lead_name: getField('full_name') || getField('first_name') + ' ' + getField('last_name'),
  lead_phone: getField('phone_number'),
  lead_email: getField('email'),
  message: 'New Facebook/Instagram lead — interested in: ' + (getField('interest') || getField('service') || 'dental services'),
  ad_name: body.entry?.[0]?.changes?.[0]?.value?.ad_name || '',
  form_id: body.entry?.[0]?.changes?.[0]?.value?.form_id || '',
  raw_source: 'facebook'
}}];

const body = $input.first().json.body || $input.first().json;
return [{ json: {
  source: 'website_form',
  channel: body.preferred_contact || 'email',
  lead_name: body.name || body.full_name || '',
  lead_phone: body.phone || body.telephone || '',
  lead_email: body.email || '',
  message: body.message || body.enquiry || body.service_interest || 'Website enquiry',
  service_interest: body.service || body.treatment || '',
  raw_source: 'website'
}}];

const body = $input.first().json.body || $input.first().json;
const isWhatsApp = (body.From || '').includes('whatsapp');
return [{ json: {
  source: isWhatsApp ? 'whatsapp' : 'sms',
  channel: isWhatsApp ? 'whatsapp' : 'sms',
  lead_name: body.ProfileName || body.From || 'Unknown',
  lead_phone: (body.From || '').replace('whatsapp:', ''),
  lead_email: '',
  message: body.Body || '',
  raw_source: isWhatsApp ? 'whatsapp' : 'sms'
}}];

const email = $input.first().json;
const nameMatch = (email.from || '').match(/^([^<]+)/);
return [{ json: {
  source: 'email',
  channel: 'email',
  lead_name: nameMatch ? nameMatch[1].trim() : 'Unknown',
  lead_phone: '',
  lead_email: (email.from || '').match(/<(.+)>/)?.[1] || email.from || '',
  message: (email.subject || '') + ' — ' + (email.text || email.snippet || '').substring(0, 500),
  raw_source: 'email'
}}];

const d = $input.first().json;
const msg = (d.message || '').toLowerCase();

// Detect treatment interest from message
let treatment = d.service_interest || 'General Enquiry';
if (msg.includes('whiten') || msg.includes('white')) treatment = 'Teeth Whitening';
else if (msg.includes('invisalign') || msg.includes('braces') || msg.includes('straight')) treatment = 'Invisalign';
else if (msg.includes('implant')) treatment = 'Dental Implants';
else if (msg.includes('veneer')) treatment = 'Veneers';
else if (msg.includes('pain') || msg.includes('hurt') || msg.includes('emergency') || msg.includes('broken') || msg.includes('cracked')) treatment = 'Emergency';
else if (msg.includes('clean') || msg.includes('checkup') || msg.includes('check-up') || msg.includes('exam')) treatment = 'General Checkup';
else if (msg.includes('root canal')) treatment = 'Root Canal';
else if (msg.includes('crown')) treatment = 'Crown';
else if (msg.includes('kid') || msg.includes('child') || msg.includes('son') || msg.includes('daughter')) treatment = 'Kids Dentistry';

// Detect urgency
const isUrgent = msg.includes('pain') || msg.includes('hurt') || msg.includes('emergency') || msg.includes('broken') || msg.includes('asap') || msg.includes('today') || msg.includes('urgent');

// Lead score (1-10)
let score = 5;
if (isUrgent) score += 3;
if (d.lead_phone) score += 1;
if (d.lead_email) score += 1;
if (d.source === 'facebook_ad') score -= 1;

const leadId = 'DEN_' + Date.now() + '_' + Math.random().toString(36).substr(2,5).toUpperCase();

return [{ json: {
  ...d,
  lead_id: leadId,
  treatment_interest: treatment,
  is_urgent: isUrgent,
  lead_score: Math.min(10, score),
  status: 'new',
  follow_up_stage: 0,
  created_at: new Date().toISOString(),
  last_updated: new Date().toISOString()
}}];

